insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$lachit-divas$t$, $t$Lachit Divas$t$, $t$লাচিত দিৱস$t$, $t$24 November, the birth anniversary of Lachit Borphukan, celebrated in Assam.$t$, $t$লাচিত বৰফুকনৰ জন্মদিন ২৪ নৱেম্বৰ, যিটো অসমত পালন কৰা হয়।$t$) on conflict (slug) do nothing;
insert into public.content (slug, kind, category_id, position) select $t$srimanta-sankardev$t$, 'gk_chapter', id, 1 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Srimanta Sankardev$t$, $t$Saint, poet, playwright and social reformer who founded Neo-Vaishnavism in Assam.$t$, 'draft', $t$Sankardev, Wikipedia: https://en.wikipedia.org/wiki/Sankardev$t$, date '2026-11-24' from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Srimanta Sankardev was a saint, poet, playwright, musician and social reformer. He was born at Bordowa in present-day Nagaon district. By tradition he was born in 1449; some historians suggest a later year. He died in 1568 at Bheladonga, in present-day Cooch Behar.$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$He founded {{term:neo-vaishnavism|Ekasarana Dharma (Neo-Vaishnavism)}}, which teaches devotion to one God through prayer and singing. He set up the {{term:sattra|Sattra}} and namghar system.$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 3, 'list', 'heritage', $t$Greatest work: Kirtan Ghosha
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$At Dhuwahat in Majuli he met Madhavdev, who became his chief disciple. Later he lived in the Koch kingdom under King Nara Narayan.$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: born at Bordowa (Nagaon); greatest work Kirtan Ghosha; chief disciple Madhavdev.$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$শ্ৰীমন্ত শংকৰদেৱ$t$, $t$অসমত নৱ-বৈষ্ণৱ ধৰ্ম প্ৰৱৰ্তন কৰা সন্ত, কবি, নাট্যকাৰ আৰু সমাজ সংস্কাৰক।$t$, 'draft', $t$Sankardev, Wikipedia: https://en.wikipedia.org/wiki/Sankardev$t$, date '2026-11-24' from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$শ্ৰীমন্ত শংকৰদেৱ আছিল এগৰাকী সন্ত, কবি, নাট্যকাৰ, সংগীতজ্ঞ আৰু সমাজ সংস্কাৰক। তেওঁৰ জন্ম বৰ্তমানৰ নগাঁও জিলাৰ বৰদোৱাত। পৰম্পৰা অনুসৰি তেওঁৰ জন্ম ১৪৪৯ চনত; কিছুমান ইতিহাসবিদে পিছৰ বছৰৰ কথা কয়। ১৫৬৮ চনত বৰ্তমানৰ কোচবিহাৰৰ ভেলাদুঙাত তেওঁৰ মৃত্যু হয়।$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$তেওঁ {{term:neo-vaishnavism|একশৰণ নামধৰ্ম (নৱ-বৈষ্ণৱ ধৰ্ম)}} প্ৰৱৰ্তন কৰে, যিয়ে নাম-প্ৰাৰ্থনাৰ জৰিয়তে এক ঈশ্বৰৰ ভক্তি শিকায়। তেওঁ {{term:sattra|সত্ৰ}} আৰু নামঘৰৰ ব্যৱস্থা গঢ়ি তোলে।$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'l1', 3, 'list', 'heritage', $t$শ্ৰেষ্ঠ গ্ৰন্থ: কীৰ্তন ঘোষা
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 4, 'paragraph', 'normal', $t$মাজুলীৰ ধুৱাহাটত তেওঁ মাধৱদেৱক লগ পায়, যিজন তেওঁৰ প্ৰধান শিষ্য হয়। পিছলৈ তেওঁ ৰজা নৰনাৰায়ণৰ কোচ ৰাজ্যত বাস কৰে।$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: জন্ম বৰদোৱাত (নগাঁও); শ্ৰেষ্ঠ গ্ৰন্থ কীৰ্তন ঘোষা; প্ৰধান শিষ্য মাধৱদেৱ।$t$, null from public.content where slug = $t$srimanta-sankardev$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$lachit-borphukan$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Lachit Borphukan$t$, $t$The Ahom general who defeated the Mughals at Saraighat in 1671.$t$, 'draft', $t$Lachit Borphukan, Wikipedia: https://en.wikipedia.org/wiki/Lachit_Borphukan$t$, date '2026-11-24' from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Lachit Borphukan was born on 24 November 1622. His father was Momai Tamuli Borbarua, a senior Ahom officer. As {{term:borphukan|Borphukan}}, Lachit was the commander of the Ahom army in the west.$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'event', $t$In 1671 he led the Ahoms to a famous naval victory over the Mughal army of Ram Singh I in the Battle of Saraighat, even though he was ill at the time.$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 3, 'paragraph', 'normal', $t$He died in April 1672. His {{term:maidam}} is at Holongapar, near Teok in Jorhat district.$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p4', 4, 'paragraph', 'normal', $t$His birthday, 24 November, is celebrated in Assam as {{term:lachit-divas|Lachit Divas}}. The best passing-out cadet of the National Defence Academy receives a gold medal named after him.$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: born 24 November 1622; Saraighat 1671; Lachit Divas 24 November.$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$লাচিত বৰফুকন$t$, $t$১৬৭১ চনত শৰাইঘাটত মোগলক পৰাস্ত কৰা আহোম সেনাপতি।$t$, 'draft', $t$Lachit Borphukan, Wikipedia: https://en.wikipedia.org/wiki/Lachit_Borphukan$t$, date '2026-11-24' from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$লাচিত বৰফুকনৰ জন্ম ১৬২২ চনৰ ২৪ নৱেম্বৰত। তেওঁৰ পিতৃ মোমাই তামুলী বৰবৰুৱা আছিল এগৰাকী জ্যেষ্ঠ আহোম বিষয়া। {{term:borphukan|বৰফুকন}} হিচাপে লাচিত পশ্চিমত আহোম সেনাৰ সেনাপতি আছিল।$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'event', $t$১৬৭১ চনত শৰাইঘাটৰ যুদ্ধত তেওঁ অসুস্থ হৈ থকা অৱস্থাতো আহোম সেনাক নেতৃত্ব দি ৰামসিংহৰ মোগল বাহিনীৰ বিৰুদ্ধে এক বিখ্যাত নৌ-যুদ্ধত জয়লাভ কৰে।$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 3, 'paragraph', 'normal', $t$১৬৭২ চনৰ এপ্ৰিলত তেওঁৰ মৃত্যু হয়। তেওঁৰ {{term:maidam|মৈদাম}} যোৰহাট জিলাৰ টিয়কৰ ওচৰৰ হোলোঙাপাৰত আছে।$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p4', 4, 'paragraph', 'normal', $t$তেওঁৰ জন্মদিন ২৪ নৱেম্বৰ অসমত {{term:lachit-divas|লাচিত দিৱস}} হিচাপে পালন কৰা হয়। ৰাষ্ট্ৰীয় প্ৰতিৰক্ষা অকাডেমীৰ শ্ৰেষ্ঠ কেডেটক তেওঁৰ নামত এটা সোণৰ পদক দিয়া হয়।$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: জন্ম ২৪ নৱেম্বৰ ১৬২২; শৰাইঘাট ১৬৭১; লাচিত দিৱস ২৪ নৱেম্বৰ।$t$, null from public.content where slug = $t$lachit-borphukan$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$lakshminath-bezbaroa$t$, 'gk_chapter', id, 3 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Lakshminath Bezbaroa$t$, $t$The father of the Assamese short story and writer of the state song.$t$, 'draft', $t$Lakshminath Bezbaroa, Wikipedia: https://en.wikipedia.org/wiki/Lakshminath_Bezbaroa$t$, date '2026-11-24' from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Lakshminath Bezbaroa (14 October 1864 to 26 March 1938) was one of the greatest writers of Assamese literature. He was a leading figure of the {{term:jonaki-era|Jonaki era}} and brought the short story into Assamese.$t$, null from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 2, 'list', 'heritage', $t$Wrote the state song 'O Mur Apunar Desh', published in his collection Kodomkoli (1913)
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$He was given the titles {{term:rasaraj|Rasaraj}} (king of humour) and Sahityarathi (charioteer of literature). He died in Dibrugarh.$t$, null from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 4, 'fact_box', 'exam_fact', $t$Remember for exams: writer of 'O Mur Apunar Desh'; pen name Kripabar Barbarua; titles Rasaraj and Sahityarathi.$t$, null from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$লক্ষ্মীনাথ বেজবৰুৱা$t$, $t$অসমীয়া চুটিগল্পৰ জনক আৰু ৰাজ্যিক সংগীতৰ ৰচয়িতা।$t$, 'draft', $t$Lakshminath Bezbaroa, Wikipedia: https://en.wikipedia.org/wiki/Lakshminath_Bezbaroa$t$, date '2026-11-24' from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$লক্ষ্মীনাথ বেজবৰুৱা (১৪ অক্টোবৰ ১৮৬৪ ৰ পৰা ২৬ মাৰ্চ ১৯৩৮) অসমীয়া সাহিত্যৰ অন্যতম শ্ৰেষ্ঠ সাহিত্যিক। তেওঁ {{term:jonaki-era|জোনাকী যুগৰ}} এগৰাকী অগ্ৰণী ব্যক্তি আছিল আৰু অসমীয়া সাহিত্যত চুটিগল্পৰ প্ৰৱৰ্তন কৰে।$t$, null from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'l1', 2, 'list', 'heritage', $t$ৰাজ্যিক সংগীত 'অ' মোৰ আপোনাৰ দেশ' ৰচনা কৰে, যিটো তেওঁৰ 'কদমকলি' (১৯১৩) সংকলনত প্ৰকাশ পায়
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$তেওঁক {{term:rasaraj|ৰসৰাজ}} আৰু সাহিত্যৰথী উপাধি দিয়া হৈছিল। ডিব্ৰুগড়ত তেওঁৰ মৃত্যু হয়।$t$, null from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 4, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: 'অ' মোৰ আপোনাৰ দেশ'ৰ ৰচয়িতা; ছদ্মনাম কৃপাবৰ বৰবৰুৱা; উপাধি ৰসৰাজ আৰু সাহিত্যৰথী।$t$, null from public.content where slug = $t$lakshminath-bezbaroa$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$jyoti-prasad-agarwala$t$, 'gk_chapter', id, 4 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Jyoti Prasad Agarwala$t$, $t$Rupkonwar, maker of the first Assamese film Joymoti.$t$, 'draft', $t$Jyoti Prasad Agarwala, Wikipedia: https://en.wikipedia.org/wiki/Jyoti_Prasad_Agarwala$t$, date '2026-11-24' from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Jyoti Prasad Agarwala (17 June 1903 to 17 January 1951) was a playwright, poet, composer and filmmaker. He is known as the {{term:rupkonwar|Rupkonwar}} of Assamese culture.$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'event', $t$In 1935 he made Joymoti, the first Assamese film, based on a play by Lakshminath Bezbaroa. He is called the founder of Assamese cinema.$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 3, 'list', 'heritage', $t$Plays: Sonit Konwari (1925), Karengar Ligiri (1930), Rupalim, Lobhita
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$He was jailed for fifteen months in 1932 for joining the freedom struggle, and went underground during the {{term:quit-india-movement|Quit India Movement}}. He discovered the young Bhupen Hazarika in Tezpur.$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$He died in Tezpur. His death anniversary, 17 January, is observed as {{term:shilpi-divas|Shilpi Divas}} (Artists' Day).$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: first Assamese film Joymoti (1935); Shilpi Divas 17 January.$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$জ্যোতিপ্ৰসাদ আগৰৱালা$t$, $t$প্ৰথম অসমীয়া চলচ্চিত্ৰ জয়মতীৰ নিৰ্মাতা ৰূপকোঁৱৰ।$t$, 'draft', $t$Jyoti Prasad Agarwala, Wikipedia: https://en.wikipedia.org/wiki/Jyoti_Prasad_Agarwala$t$, date '2026-11-24' from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$জ্যোতিপ্ৰসাদ আগৰৱালা (১৭ জুন ১৯০৩ ৰ পৰা ১৭ জানুৱাৰী ১৯৫১) আছিল নাট্যকাৰ, কবি, সুৰকাৰ আৰু চলচ্চিত্ৰ নিৰ্মাতা। তেওঁ অসমীয়া সংস্কৃতিৰ {{term:rupkonwar|ৰূপকোঁৱৰ}} হিচাপে জনাজাত।$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'event', $t$১৯৩৫ চনত তেওঁ লক্ষ্মীনাথ বেজবৰুৱাৰ নাটকৰ আধাৰত প্ৰথম অসমীয়া চলচ্চিত্ৰ 'জয়মতী' নিৰ্মাণ কৰে। তেওঁক অসমীয়া চলচ্চিত্ৰৰ জনক বুলি কোৱা হয়।$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'l1', 3, 'list', 'heritage', $t$নাটক: শোণিত কুঁৱৰী (১৯২৫), কাৰেঙৰ লিগিৰী (১৯৩০), ৰূপালীম, লভিতা
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 4, 'paragraph', 'normal', $t$স্বাধীনতা সংগ্ৰামত যোগ দিয়াৰ বাবে ১৯৩২ চনত তেওঁ পোন্ধৰ মাহ কাৰাবাস খাটে, আৰু {{term:quit-india-movement|ভাৰত ত্যাগ আন্দোলনৰ}} সময়ত আত্মগোপন কৰে। তেজপুৰত তেওঁ কিশোৰ ভূপেন হাজৰিকাক আৱিষ্কাৰ কৰে।$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$তেজপুৰত তেওঁৰ মৃত্যু হয়। তেওঁৰ মৃত্যু দিৱস ১৭ জানুৱাৰী {{term:shilpi-divas|শিল্পী দিৱস}} হিচাপে পালন কৰা হয়।$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: প্ৰথম অসমীয়া চলচ্চিত্ৰ জয়মতী (১৯৩৫); শিল্পী দিৱস ১৭ জানুৱাৰী।$t$, null from public.content where slug = $t$jyoti-prasad-agarwala$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$gopinath-bordoloi$t$, 'gk_chapter', id, 5 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Gopinath Bordoloi$t$, $t$The first Chief Minister of Assam, who helped keep Assam in India.$t$, 'draft', $t$Gopinath Bordoloi, Wikipedia: https://en.wikipedia.org/wiki/Gopinath_Bordoloi
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Gopinath Bordoloi was born on 6 June 1890 at Raha in Nagaon district and died on 5 August 1950 in Guwahati.$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$He became Premier of Assam in 1938 and was the first Chief Minister of Assam, from 11 February 1946 until his death.$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 3, 'paragraph', 'event', $t$In 1946 the {{term:cabinet-mission|Cabinet Mission}} plan put Assam in a group with Bengal. Under Bordoloi, the Assam Congress opposed this grouping, which helped Assam remain part of India.$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p4', 4, 'paragraph', 'normal', $t$He was awarded the Bharat Ratna after his death, in 1999. He is remembered as Lokapriya (beloved of the people).$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: first Chief Minister of Assam; opposed the Grouping plan (1946); Bharat Ratna 1999.$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$গোপীনাথ বৰদলৈ$t$, $t$অসমক ভাৰতত ৰখাত সহায় কৰা অসমৰ প্ৰথম মুখ্যমন্ত্ৰী।$t$, 'draft', $t$Gopinath Bordoloi, Wikipedia: https://en.wikipedia.org/wiki/Gopinath_Bordoloi
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$গোপীনাথ বৰদলৈৰ জন্ম ১৮৯০ চনৰ ৬ জুনত নগাঁও জিলাৰ ৰহাত আৰু মৃত্যু ১৯৫০ চনৰ ৫ আগষ্টত গুৱাহাটীত।$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$১৯৩৮ চনত তেওঁ অসমৰ প্ৰধানমন্ত্ৰী হয় আৰু ১৯৪৬ চনৰ ১১ ফেব্ৰুৱাৰীৰ পৰা মৃত্যুলৈকে অসমৰ প্ৰথম মুখ্যমন্ত্ৰী আছিল।$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 3, 'paragraph', 'event', $t$১৯৪৬ চনত {{term:cabinet-mission|কেবিনেট মিছনৰ}} পৰিকল্পনাত অসমক বংগৰ সৈতে একেটা গোটত ৰখা হৈছিল। বৰদলৈৰ নেতৃত্বত অসম কংগ্ৰেছে এই গোটকৰণৰ বিৰোধিতা কৰে, যাৰ ফলত অসম ভাৰতৰ অংশ হৈ থাকিল।$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p4', 4, 'paragraph', 'normal', $t$মৃত্যুৰ পিছত ১৯৯৯ চনত তেওঁক ভাৰতৰত্ন প্ৰদান কৰা হয়। তেওঁক লোকপ্ৰিয় বুলি সোঁৱৰা হয়।$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: অসমৰ প্ৰথম মুখ্যমন্ত্ৰী; গোটকৰণ পৰিকল্পনাৰ বিৰোধিতা (১৯৪৬); ভাৰতৰত্ন ১৯৯৯।$t$, null from public.content where slug = $t$gopinath-bordoloi$t$ on conflict do nothing;
