insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Bhupen Hazarika$t$, $t$Sudhakantha, the bard of the Brahmaputra and Bharat Ratna awardee.$t$, 'draft', $t$Bhupen Hazarika, Wikipedia: https://en.wikipedia.org/wiki/Bhupen_Hazarika$t$, date '2026-11-24' from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Bhupen Hazarika was born on 8 September 1926 at Sadiya and died on 5 November 2011 in Mumbai. He was a singer, composer, poet and filmmaker, known as {{term:sudhakantha|Sudhakantha}} and the bard of the Brahmaputra.$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$He earned a PhD from Columbia University, New York, in 1952. His famous songs include 'Bistirno Parore' and 'Manuhe Manuhor Babe'.$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 3, 'list', 'verified_fact', $t$Sangeet Natak Akademi Award: 1987
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$His film Shakuntala (1961) won the National Award for the best Assamese film. The Dhola-Sadiya bridge over the Lohit is named after him.$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: born at Sadiya; Dadasaheb Phalke 1992; Bharat Ratna 2019; Dhola-Sadiya bridge named after him.$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$ড° ভূপেন হাজৰিকা$t$, $t$সুধাকণ্ঠ, ব্ৰহ্মপুত্ৰৰ কবি আৰু ভাৰতৰত্ন বঁটা প্ৰাপক।$t$, 'draft', $t$Bhupen Hazarika, Wikipedia: https://en.wikipedia.org/wiki/Bhupen_Hazarika$t$, date '2026-11-24' from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$ভূপেন হাজৰিকাৰ জন্ম ১৯২৬ চনৰ ৮ ছেপ্টেম্বৰত শদিয়াত আৰু মৃত্যু ২০১১ চনৰ ৫ নৱেম্বৰত মুম্বাইত। তেওঁ আছিল গায়ক, সুৰকাৰ, কবি আৰু চলচ্চিত্ৰ নিৰ্মাতা, {{term:sudhakantha|সুধাকণ্ঠ}} আৰু ব্ৰহ্মপুত্ৰৰ কবি হিচাপে জনাজাত।$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$১৯৫২ চনত তেওঁ নিউয়ৰ্কৰ কলম্বিয়া বিশ্ববিদ্যালয়ৰ পৰা পি এইচ ডি লাভ কৰে। তেওঁৰ বিখ্যাত গীতৰ ভিতৰত আছে 'বিস্তীৰ্ণ পাৰৰে' আৰু 'মানুহে মানুহৰ বাবে'।$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'l1', 3, 'list', 'verified_fact', $t$সংগীত নাটক অকাডেমী বঁটা: ১৯৮৭
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 4, 'paragraph', 'normal', $t$তেওঁৰ চলচ্চিত্ৰ 'শকুন্তলা' (১৯৬১)ই শ্ৰেষ্ঠ অসমীয়া চলচ্চিত্ৰৰ ৰাষ্ট্ৰীয় বঁটা লাভ কৰে। লুইতৰ ওপৰৰ ঢোলা-শদিয়া দলং তেওঁৰ নামেৰে নামকৰণ কৰা হৈছে।$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: জন্ম শদিয়াত; দাদাচাহেব ফাল্কে ১৯৯২; ভাৰতৰত্ন ২০১৯; ঢোলা-শদিয়া দলং তেওঁৰ নামত।$t$, null from public.content where slug = $t$bhupen-hazarika$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$maniram-dewan$t$, 'gk_chapter', id, 7 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Maniram Dewan$t$, $t$Tea pioneer and martyr of 1857 in Assam.$t$, 'draft', $t$Maniram Dewan, Wikipedia: https://en.wikipedia.org/wiki/Maniram_Dewan
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Maniram Dutta Barua, known as Maniram Dewan, was a nobleman who first worked with the British and later turned against them.$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$He guided Robert Bruce to the Singpho chief Bessa Gam, which led to the discovery of Assam tea. In 1839 he became the {{term:dewan|Dewan}} of the Assam Tea Company at Nazira. He later started his own garden at Cinnamara, becoming the first Indian to grow tea commercially in Assam.$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 3, 'paragraph', 'event', $t$During the revolt of 1857 he planned a rising to bring back Ahom rule. The plot was discovered, and he was hanged at Jorhat jail on 26 February 1858, along with Piyali Barua.$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 4, 'fact_box', 'exam_fact', $t$Remember for exams: first Indian tea planter in Assam; hanged at Jorhat on 26 February 1858 with Piyali Barua.$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$মণিৰাম দেৱান$t$, $t$চাহ উদ্যোগৰ অগ্ৰদূত আৰু অসমত ১৮৫৭ চনৰ শ্বহীদ।$t$, 'draft', $t$Maniram Dewan, Wikipedia: https://en.wikipedia.org/wiki/Maniram_Dewan
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$মণিৰাম দত্ত বৰুৱা, যাক মণিৰাম দেৱান বুলি জনা যায়, এগৰাকী অভিজাত ব্যক্তি আছিল, যিয়ে প্ৰথমে ব্ৰিটিছৰ সৈতে কাম কৰিছিল আৰু পিছত তেওঁলোকৰ বিৰোধী হৈ পৰে।$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$তেওঁ ৰবাৰ্ট ব্ৰুছক চিংফৌ মুখিয়াল বিছা গামৰ ওচৰলৈ লৈ যায়, যাৰ ফলত অসমৰ চাহ আৱিষ্কাৰ হয়। ১৮৩৯ চনত তেওঁ নাজিৰাৰ আসাম টি কোম্পানীৰ {{term:dewan|দেৱান}} হয়। পিছত চিনামৰাত নিজৰ বাগিচা আৰম্ভ কৰি তেওঁ অসমত বাণিজ্যিকভাৱে চাহ খেতি কৰা প্ৰথম ভাৰতীয় হয়।$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 3, 'paragraph', 'event', $t$১৮৫৭ চনৰ বিদ্ৰোহৰ সময়ত তেওঁ আহোম শাসন ঘূৰাই আনিবলৈ বিদ্ৰোহৰ পৰিকল্পনা কৰে। ষড়যন্ত্ৰ ধৰা পৰে আৰু ১৮৫৮ চনৰ ২৬ ফেব্ৰুৱাৰীত পিয়লি বৰুৱাৰ সৈতে যোৰহাট কাৰাগাৰত তেওঁক ফাঁচি দিয়া হয়।$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 4, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: অসমৰ প্ৰথম ভাৰতীয় চাহ খেতিয়ক; ২৬ ফেব্ৰুৱাৰী ১৮৫৮ত পিয়লি বৰুৱাৰ সৈতে যোৰহাটত ফাঁচি।$t$, null from public.content where slug = $t$maniram-dewan$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$kanaklata-barua$t$, 'gk_chapter', id, 8 from public.categories where slug = $t$personalities$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Kanaklata Barua$t$, $t$The 17-year-old martyr of Gohpur in the Quit India Movement.$t$, 'draft', $t$Kanaklata Barua, Wikipedia: https://en.wikipedia.org/wiki/Kanaklata_Barua
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'personality', $t$Kanaklata Barua was born on 22 December 1924 at Borangabari, Gohpur, in the old Darrang district.$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 2, 'paragraph', 'event', $t$During the {{term:quit-india-movement|Quit India Movement}} she joined the {{term:mrityu-bahini|Mrityu Bahini}}. On 20 September 1942 she led a procession carrying the national flag towards the Gohpur police station and was shot dead by the police. She was 17 years old.$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 3, 'paragraph', 'normal', $t$She is remembered as one of the youngest martyrs of India's freedom struggle, and is also called Birbala.$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 4, 'fact_box', 'exam_fact', $t$Remember for exams: martyred at Gohpur on 20 September 1942, aged 17; member of the Mrityu Bahini.$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$কনকলতা বৰুৱা$t$, $t$ভাৰত ত্যাগ আন্দোলনত গহপুৰৰ ১৭ বছৰীয়া শ্বহীদ।$t$, 'draft', $t$Kanaklata Barua, Wikipedia: https://en.wikipedia.org/wiki/Kanaklata_Barua
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'personality', $t$কনকলতা বৰুৱাৰ জন্ম ১৯২৪ চনৰ ২২ ডিচেম্বৰত পুৰণি দৰং জিলাৰ গহপুৰৰ বৰঙাবাৰীত।$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 2, 'paragraph', 'event', $t${{term:quit-india-movement|ভাৰত ত্যাগ আন্দোলনৰ}} সময়ত তেওঁ {{term:mrityu-bahini|মৃত্যু বাহিনীত}} যোগ দিয়ে। ১৯৪২ চনৰ ২০ ছেপ্টেম্বৰত তেওঁ ৰাষ্ট্ৰীয় পতাকা লৈ গহপুৰ থানালৈ এক শোভাযাত্ৰাৰ নেতৃত্ব দিয়ে আৰু আৰক্ষীৰ গুলীত শ্বহীদ হয়। তেতিয়া তেওঁৰ বয়স আছিল ১৭ বছৰ।$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 3, 'paragraph', 'normal', $t$ভাৰতৰ স্বাধীনতা সংগ্ৰামৰ আটাইতকৈ কম বয়সীয়া শ্বহীদসকলৰ এগৰাকী হিচাপে তেওঁক সোঁৱৰা হয়, আৰু তেওঁক বীৰবালা বুলিও কোৱা হয়।$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 4, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ২০ ছেপ্টেম্বৰ ১৯৪২ত গহপুৰত ১৭ বছৰ বয়সত শ্বহীদ; মৃত্যু বাহিনীৰ সদস্য।$t$, null from public.content where slug = $t$kanaklata-barua$t$ on conflict do nothing;
